productCard.scss:
$black:  #0f0f0f;
$white:  #ffffff;
$red:  #E82222;
$green: #08BC72;
$grey:  #868686;



.body{
    .card{
        .card-figure{
            border: none;
            position: relative;
            .flags{
                display: flex;
                height: max-content;
                z-index: 1;
                flex-direction: column;
                gap: 4px;
                position: absolute;
                top: 4px;
                .sale-flag, .new-flag, .outlet-flag, .recommended-flag{
                    box-sizing: border-box;
                    display: flex;
                    align-items: center;
                    padding: 2px 11px;
                    width: max-content;
                    padding: 2px 10px 2px 10px;
                    border-radius: 30px;
                    .sale-text, .new-text, .outlet-text, .recommended-text{
                        color: $white;
                        font-size: 14px;
                        font-weight: 700;
                        text-transform: uppercase;
                    }
                }
                .sale-flag{
                    background-color: stencilColor("color_badge_product_sale_badges");
                }
                .new-flag{
                    background-color: stencilColor("color_badge_new_product");
                }
                .outlet-flag{
                    background-color: stencilColor("color_badge_product_outlet");
                }
                .recommended-flag{
                    background-color: stencilColor("color_badge_product_recommended");
                }
            }
            .card-figcaption{
                border: none;
                background-color: transparent;
                .card-figcaption-body{
                    border: 1px solid $black;
                    border-radius: 10px;
                    padding: 14px;
                    background-color: $white;
                    .color-swatch {
                        display: inline-block;
                        width: 30px;
                        height: 30px;
                        border: 1px solid #ccc;
                        cursor: pointer;
                        margin-right: 10px;
                        border-radius: 50%;
                        overflow: hidden;
                        position: relative;
                    }

                    .color-slice {
                        position: absolute;
                        top: 0;
                        height: 100%;
                        width: 100%;
                    }

                    /* Split for 2-part swatches */
                    .split-2.slice-1 {
                        width: 50%;
                        left: 0;
                        border-radius: 50% 0 0 50%;
                    }

                    .split-2.slice-2 {
                        width: 50%;
                        left: 50%;
                        border-radius: 0 50% 50% 0;
                    }

                    /* Split for 3-part swatches */
                    .split-3.slice-1 {
                        width: 33.33%;
                        left: 0;
                        border-radius: 50% 0 0 50%;
                    }

                    .split-3.slice-2 {
                        width: 33.33%;
                        left: 33.33%;
                    }

                    .split-3.slice-3 {
                        width: 33.33%;
                        left: 66.66%;
                        border-radius: 0 50% 50% 0;
                    }

                    .size-option {
                        display: inline-block;
                        padding: 2px 10px;
                        border: 1px solid black;
                        border-radius: 10px;
                        cursor: pointer;
                        margin-right: 10px;
                        margin-bottom: 4px;
                    }

                    .size-option.selected, .color-swatch.selected {
                        border-color: black;
                    }

                    .option-wrapper {
                        margin-bottom: 8px;
                        label{
                            display: block;
                            font-size: 14px;
                            font-weight: 300;
                            margin-bottom: 4px;
                        }
                    }
                    .color-swatch.active {
                        border: 2px solid black;
                    }

                    .size-option.active {
                        border: 2px solid black;
                        background-color: black; 
                        color: white;
                    }
                    .button.button--primary{
                        justify-content: center;
                    }
                    #product-form-container{
                        width: 100%;
                    }
                    .card-figcaption--action-buttons{
                        gap: 5px;
                        .button.button--primary{
                            font-size: 15px;
                            display: flex;
                            margin-left: auto;
                            margin-right: auto;
                            width: 80%;
                            max-width: 300px;
                            background-color: $button--primary-backgroundColor;
                        }
                        .button.button--primary:hover{
                            background-color: $buttonStyle-primary-backgroundColorHover;
                            color: $white;
                        }
                    }

                    .addtocart-wrapper{
                        margin-top: 15px;
                        .button.button--primary{
                            font-size: 16px;
                            display: flex;
                            margin-left: auto;
                            margin-right: auto;
                            width: 80%;
                            max-width: 300px;
                        }
                        .button.button--primary:hover{
                            background-color: $buttonStyle-primary-backgroundColorHover;
                            color: $white;
                        }
                    }
                }
            }
        }
        .card-body{
            background-color: $white;
            .card-main{
                .card-text.brand-name{
                    font-weight: 300;
                }
                .card-title{
                    color: $black;
                    font-weight: 300;
                    //word-break: break-all;
                }
                .card-text{
                    .price-section.price-section--withTax{
                        display: flex;
                        flex-direction: row-reverse;
                        align-self: flex-end;
                        width: 100%;
                        justify-content: flex-end;
                        gap: 20px;
                        .price.price--withTax, .price{
                            font-weight: 700;
                        }
                        .price.red{
                            color: $red;
                        }
                        .price-section.price-section--withTax.non-sale-price--withTax{
                            width: auto;
                            .price.price--non-sale{
                                font-weight: 300;
                                color: $grey;
                                margin-right: 0;
                                margin-left: 0;
                            }
                            .saving{
                                display: none;
                            }
                        }
                    }
                    .price-section.price-section--withTax.range{
                        gap: 0;
                        .from{
                            display: block;
                            width: 100%;
                        }
                    }
                }
                width: 100%;
            }
            .card-details{

                .card-compare-container{
                    display: flex;
                    justify-content: space-between;
                    flex-wrap: wrap;
                    .card-compare{
                        text-align: right;
                        cursor: pointer;
                        font-weight: 700;
                        font-size: 13px;
                        text-decoration: underline;
                        .compare-input{
                            display: none;
                        }
                    }
                    .compare-button-wrap{
                        margin: 5px 0 0;
                        .compare-button.show{

                        }
                    }
                }
            }
        }
    }
}

@media (min-width: 800px) {
    .body{
        .productGrid{
            .product{
                margin-bottom: 60px;
            }
        }
        .card{
            .card-body{
                //padding-top: 0.9rem;
                padding-top: 0px;
                .card-main{
                    .card-text.brand-name{
                        font-size: 14px;
                    }
                    .card-title{
                        font-size: 18px;
                    }
                    .card-description{
                        padding-top:calc(3px+00.9rem);
                    }

                    .card-text{
                        .price-section.price-section--withTax{
                            .price.price--withTax, .price{
                                font-size: 20px;
                            }
                            .price-section.price-section--withTax.non-sale-price--withTax{
                                .price.price--non-sale{
                                    font-size: 18px;
                                }
                            }
                        }
                    }
                }
            }
            .card-details{
                .card-compare-container{
                    .colors-info{
                        .sizes{
                            display: none;
                        }
                    }
                }
            }
        }
    }
}

@media (max-width: 800px) {
    .body{
        .productGrid{
            .product{
                margin-bottom: 35px;
                height: fit-content;
            }
        }
        .card{
            .card-figure{
                max-height: 165px;
                .flags{
                    .sale-flag, .new-flag, .outlet-flag, .recommended-flag{
                        padding: 2px 10px 2px 10px;
                        .sale-text, .new-text, .outlet-text, .recommended-text{
                            font-size: 12px;
                        }
                    }
                }
            }
            .card-body{
                padding-top: 0px;
                .card-main{
                    .card-text.brand-name{
                        font-size: 12px;
                    }
                    .card-title{
                        font-size: 16px;
                    }
                    .card-text{
                        .price-section.price-section--withTax{
                            gap: 8px;
                            .price.price--withTax, .price{
                                font-size: 16px;
                            }
                            .price-section.price-section--withTax.non-sale-price--withTax{
                                .price.price--non-sale{
                                    font-size: 14px;
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}
